import{describe,it,expect}from"vitest";import{REGIONS_DATASET,validateDataset,checkClassification,shuffleDataset,calculateSorterScore}from"../../frontend/union-territory-sorter/union-territory-sorter.js";describe("Union Territory Sorter Dataset Integrity",()=>{it("contains exactly 36 regions in total",()=>{expect(REGIONS_DATASET.length).toBe(36)}),it("validates exactly 28 states and 8 union territories",()=>{const e=validateDataset(REGIONS_DATASET);expect(e.isValid).toBe(!0),expect(e.statesCount).toBe(28),expect(e.utCount).toBe(8),expect(e.totalCount).toBe(36),expect(e.duplicateIds).toEqual([])}),it("every entry has non-empty required fields (id, name, type, capital, info)",()=>{REGIONS_DATASET.forEach(e=>{expect(e).toHaveProperty("id"),expect(e).toHaveProperty("name"),expect(e).toHaveProperty("type"),expect(e).toHaveProperty("capital"),expect(e).toHaveProperty("info"),expect(typeof e.id).toBe("string"),expect(typeof e.name).toBe("string"),expect(typeof e.capital).toBe("string"),expect(typeof e.info).toBe("string"),expect(["state","ut"]).toContain(e.type),expect(e.id.trim().length).toBeGreaterThan(0),expect(e.name.trim().length).toBeGreaterThan(0),expect(e.capital.trim().length).toBeGreaterThan(0)})}),it("all 8 Union Territories are correctly cataloged",()=>{const e=REGIONS_DATASET.filter(e=>"ut"===e.type).map(e=>e.id);expect(e.length).toBe(8),["AN","CH","DH","DL","JK","LA","LD","PY"].forEach(t=>{expect(e).toContain(t)})})}),describe("Classification Logic",()=>{it("correctly classifies Jammu and Kashmir as a Union Territory",()=>{const e=checkClassification("JK","ut");expect(e.isValidRegion).toBe(!0),expect(e.isCorrect).toBe(!0),expect(e.expectedType).toBe("ut");const t=checkClassification("JK","state");expect(t.isCorrect).toBe(!1)}),it("correctly classifies Maharashtra as a State",()=>{const e=checkClassification("MH","state");expect(e.isCorrect).toBe(!0),expect(e.expectedType).toBe("state");const t=checkClassification("MH","ut");expect(t.isCorrect).toBe(!1)}),it("handles case-insensitivity and whitespace in target choices",()=>{expect(checkClassification("DL"," UT ").isCorrect).toBe(!0),expect(checkClassification("RJ"," STATE ").isCorrect).toBe(!0)}),it("returns invalid region result for non-existent region ID",()=>{const e=checkClassification("INVALID_ID","state");expect(e.isValidRegion).toBe(!1),expect(e.isCorrect).toBe(!1),expect(e.expectedType).toBeNull()})}),describe("Deck Shuffling",()=>{it("returns a new array of 36 items without mutating original dataset",()=>{const e=shuffleDataset(REGIONS_DATASET);expect(e.length).toBe(36),expect(e).not.toBe(REGIONS_DATASET);const t=REGIONS_DATASET.map(e=>e.id).sort(),c=e.map(e=>e.id).sort();expect(c).toEqual(t)})}),describe("Sorter Scoring Engine",()=>{it("calculates perfect score, grade S, and speed bonus for 36/36 in 90 seconds",()=>{const e=calculateSorterScore(36,36,90);expect(e.accuracyPct).toBe(100),expect(e.basePoints).toBe(3600),expect(e.speedBonus).toBeGreaterThan(0),expect(e.grade).toBe("S"),expect(e.title).toBe("Master Geographer")}),it("calculates Grade A for 75% accuracy (27/36 correct)",()=>{const e=calculateSorterScore(27,36,120);expect(e.accuracyPct).toBe(75),expect(e.grade).toBe("A"),expect(e.title).toBe("Regional Scholar")}),it("handles 0 correct answers gracefully",()=>{const e=calculateSorterScore(0,36,150);expect(e.accuracyPct).toBe(0),expect(e.totalScore).toBe(0),expect(e.grade).toBe("C"),expect(e.title).toBe("Explorer Trainee")}),it("safely bounds out-of-range counts",()=>{const e=calculateSorterScore(50,36,10);expect(e.correctCount).toBe(36);const t=calculateSorterScore(-5,36,10);expect(t.correctCount).toBe(0)})});